// Copies openapi-typescript output from the api-specs repo into src/generated/.
// Generated files are never hand-edited; rerun this script after the contract changes.
//
//   node scripts/sync-api-types.mjs [--generate]
//
// API_SPECS_DIR   path to a local api-specs clone (default: ../api-specs)
// --generate      run `make generate-ts` in api-specs first (needs its toolchain)
import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const specs = resolve(process.env.API_SPECS_DIR ?? join(root, "..", "api-specs"));
const src = join(specs, "gen", "ts");
const dest = join(root, "src", "generated");

if (process.argv.includes("--generate")) {
  execFileSync("make", ["generate-ts"], { cwd: specs, stdio: "inherit" });
}

if (!existsSync(src)) {
  console.error(`No generated types at ${src}. Run with --generate, or set API_SPECS_DIR.`);
  process.exit(1);
}

mkdirSync(dest, { recursive: true });
const services = [];
for (const file of readdirSync(src).filter((f) => f.endsWith(".d.ts")).sort()) {
  copyFileSync(join(src, file), join(dest, file));
  services.push(file.replace(/\.d\.ts$/, ""));
  console.log(`copied ${file}`);
}

const index =
  "// GENERATED by scripts/sync-api-types.mjs from api-specs. Do not edit.\n" +
  services.map((s) => `export type * as ${s} from "./${s}";`).join("\n") +
  "\n";
writeFileSync(join(dest, "index.ts"), index);
console.log(`wrote index.ts for: ${services.join(", ")}`);
